                            FILTER( ALLSELECTED('Production and Sales Inventory'[WEEK]), 'Production and Sales Inventory'[WEEK] <= LastVisibleDate

                                  )
                             )


return working_output

var total_dmd_pallets = sum('Production and Sales Inventory'[Total_Demand_Pallet])
var dropdown =  sum('Factor Dropdown'[Dropdown %])
return (total_dmd_pallets*dropdown)

var LastVisibleDate =  MAX('Production and Sales Inventory'[WEEK])

 var rolling_sum_unattained_dmd = 
                    CALCULATE(SUM('Production and Sales Inventory'[Total_Demand_Pallet]) - [CS - Total Demand Palelts -(ADJ)]*(1 - 0.1), 
                            FILTER( ALLSELECTED('Production and Sales Inventory'[WEEK]), 'Production and Sales Inventory'[WEEK] <= LastVisibleDate

                                  )
                             )

var onhand_rolling_sum =  [Onhand PAL] + rolling_sum_unattained_dmd
return divide(onhand_rolling_sum,[Max Pallet by Division],0)

